class Window(SQLiteNumericMixin, Expression):
    template = '%(expression)s OVER (%(window)s)'
    # Although the main expression may either be an aggregate or an
    # expression with an aggregate function, the GROUP BY that will
    # normally be added by the compiler needs to be suppressed.
    # The window expression itself takes care of the appropriate
    # grouping.
    contains_aggregate = False

    def __init__(self, expression, partition_by=None, order_by=None, frame=None):
        self.expression = expression
        self.partition_by = partition_by
        self.order_by = order_by
        self.frame = frame
        super().__init__()

    def as_sql(self, compiler, connection, **extra_context):
        connection.ops.check_expression_support(self)
        if connection.vendor == 'sqlite':
            expr_sql, params = self.expression.as_sql(compiler, connection)
        else:
            expr_sql, params = compiler.compile(self.expression)
        window_sql, window_params = self.as_window(compiler, connection)
        sql = self.template % {'expression': expr_sql, 'window': window_sql}
        return sql, params + window_params

    def as_window(self, compiler, connection):
        window_parts = []
        if self.partition_by:
            partition_by_sql, partition_by_params = compiler.compile(self.partition_by)
            window_parts.append('PARTITION BY %s' % partition_by_sql)
        if self.order_by:
            order_by_sql, order_by_params = compiler.compile(self.order_by)
            window_parts.append('ORDER BY %s' % order_by_sql)
        if self.frame:
            window_parts.append(self.frame)
        return ' '.join(window_parts), []

    def __repr__(self):
        return '<%s: %s>' % (self.__class__.__name__, self)

    def __str__(self):
        return self.as_sql(None, None)[0]

    def copy(self):
        return self

    def resolve_expression(self, *args, **kwargs):
        return self

    def get_source_expressions(self):
        return [self.expression]

    def set_source_expressions(self, exprs):
