def technical_500_response(request, exc_type, exc_value, tb, status_code=500, exception_reporter=None):
    """
    Create a technical server error response. The last three arguments are
    the values returned from sys.exc_info() and friends.
    """
    if exception_reporter is None:
        exception_reporter = getattr(settings, 'DEFAULT_EXCEPTION_REPORTER', None)

    if isinstance(exception_reporter, str):
        exception_reporter = import_string(exception_reporter)

    if exception_reporter is None:
        exception_reporter = ExceptionReporter

    reporter = exception_reporter(request, exc_type, exc_value, tb)
    if request.is_ajax():
        text = reporter.get_traceback_text()
        return HttpResponse(text, status=status_code, content_type='text/plain; charset=utf-8')
    else:
        html = reporter.get_traceback_html()
        return HttpResponse(html, status=status_code, content_type='text/html')

