def _dijkstra(sys1, sys2):
    # Use Dijkstra algorithm to find the shortest path between two indirectly-connected
    # coordinate systems
    relations = sys1.relations
    graph = {}
    for s1, s2 in relations.keys():
        if s1 not in graph:
            graph[s1] = {s2}
        else:
            graph[s1].add(s2)
        if s2 not in graph:
            graph[s2] = {s1}
        else:
            graph[s2].add(s1)

    all_sys = {cs.name: cs for cs in sys1.patch.coord_systems}
    start_node = sys1.name
    end_node = sys2.name

    if start_node not in graph:
        raise NotImplementedError(f"No transformation path found between {sys1} and {sys2}")

    path_dict = {sys:[0, [], 0] for sys in graph} # minimum distance, path, times of visited

    def visit(sys):
        path_dict[sys][2] = 1
        for newsys in graph[sys]:
            distance = path_dict[sys][0] + 1
            if path_dict[newsys][0] >= distance or not path_dict[newsys][1]:
                path_dict[newsys][0] = distance
                path_dict[newsys][1] = [i for i in path_dict[sys][1]]
                path_dict[newsys][1].append(sys)

    visit(start_node)

    while True:
        min_distance = max(path_dict.values(), key=lambda x:x[0])[0]
        newsys = None
        for sys, lst in path_dict.items():
            if 0 < lst[0] <= min_distance and not lst[2]:
                min_distance = lst[0]
                newsys = sys
        if newsys is None:
            break
        visit(newsys)

    if end_node not in path_dict or not path_dict[end_node][1]:
        raise NotImplementedError(f"No transformation path found between {sys1} and {sys2}")

    path_of_names = path_dict[end_node][1] + [end_node]
    return [all_sys[name] for name in path_of_names]

